tool.command:

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

mddb

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__project_id__dq__:__dq__${properties.project_id}__dq__,__dq__node_id__dq__:__dq__${properties.node_id}__dq__,__dq__trj_format__dq__:__dq__${properties.trj_format}__dq__,__dq__frames__dq__:__dq__${properties.frames}__dq__,__dq__selection__dq__:__dq__${properties.selection}__dq__,__dq__extra_files__dq__:${properties.extra_files}__cc____cc__'
  #end if


  --output_top_path $outname_output_top_path

  --output_trj_path $outname_output_trj_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if


  if test -f $outname_output_top_path; then mv $outname_output_top_path $output_top_path; fi;

  if test -f $outname_output_trj_path; then mv $outname_output_trj_path $output_trj_path; fi;
